 }
+
+/**
+ * 使用者對 AI 工具按讚（收藏）
+ * @param aiToolId - AI 工具 ID（API 使用 id，非 slug）
+ */
+export async function likeAiTool(aiToolId: string) {
+  const user = await currentUser();
+  if (!user?.id) {
+    throw new Error(ERROR_IDS.LOGIN_REQUIRED);
+  }
+
+  await prisma.aiToolLike
+    .create({
+      data: {
+        aiToolId,
+        userId: user.id
+      }
+    })
+    .catch((error: { code?: string }) => {
+      if (error.code === 'P2002') {
+        return;
+      }
+      throw error;
+    });
+}
+
+/**
+ * 使用者取消對 AI 工具的按讚
+ * @param aiToolId - AI 工具 ID
+ */
+export async function unlikeAiTool(aiToolId: string) {
+  const user = await currentUser();
+  if (!user?.id) {
+    throw new Error(ERROR_IDS.LOGIN_REQUIRED);
+  }
+
+  await prisma.aiToolLike.deleteMany({
+    where: {
+      aiToolId,
+      userId: user.id
+    }
+  });
+}
