+import { likeAiTool, unlikeAiTool } from '@/actions/ai-tool';
+import { ERROR_IDS } from '@/constants/errorIds';
+import { currentUser } from '@/lib/auth';
+import createLogger from '@/lib/logger';
+
+const logger = createLogger('api-ai-tools-like');
+
+export async function PATCH(
+  _request: Request,
+  { params }: { params: Promise<{ id: string }> }
+) {
+  const user = await currentUser();
+  if (!user?.id) {
+    return Response.json(
+      { error: ERROR_IDS.LOGIN_REQUIRED },
+      { status: 401 }
+    );
+  }
+
+  const { id } = await params;
+  try {
+    await likeAiTool(id);
+    return Response.json({ success: true });
+  } catch (error) {
+    logger.error(
+      ERROR_IDS.AI_TOOL_LIKE_FAILED,
+      error instanceof Error ? error : { cause: String(error) },
+      { aiToolId: id }
+    );
+    return Response.json(
+      { success: false, error: ERROR_IDS.AI_TOOL_LIKE_FAILED },
+      { status: 500 }
+    );
+  }
+}
+
+export async function DELETE(
+  _request: Request,
+  { params }: { params: Promise<{ id: string }> }
+) {
+  const user = await currentUser();
+  if (!user?.id) {
+    return Response.json(
+      { error: ERROR_IDS.LOGIN_REQUIRED },
+      { status: 401 }
+    );
+  }
+
+  const { id } = await params;
+  try {
+    await unlikeAiTool(id);
+    return Response.json({ success: true });
+  } catch (error) {
+    logger.error(
+      ERROR_IDS.AI_TOOL_LIKE_FAILED,
+      error instanceof Error ? error : { cause: String(error) },
+      { aiToolId: id }
+    );
+    return Response.json(
+      { success: false, error: ERROR_IDS.AI_TOOL_LIKE_FAILED },
+      { status: 500 }
+    );
+  }
+}
