+'use client';
+
+import { useTranslations } from 'next-intl';
+
+import { Badge } from '@/components/ui/badge';
+import { tagNamesToQuickTagKeys } from '@/lib/ai-tool-quick-tag';
+
+type TagItem = { tag: { id: string; name: string } };
+
+interface AiToolCategoryCellProps {
+  tags: TagItem[];
+}
+
+/**
+ * 後台列表「分類」欄：若標籤中有符合快速分類的 tag，顯示對應分類標籤
+ */
+export function AiToolCategoryCell({ tags }: AiToolCategoryCellProps) {
+  const t = useTranslations('common');
+
+  const tagNames = tags?.map((item) => item.tag.name) ?? [];
+  const quickTagKeys = tagNamesToQuickTagKeys(tagNames);
+
+  if (quickTagKeys.length === 0) {
+    return <span className="text-muted-foreground">-</span>;
+  }
+
+  return (
+    <div className="flex flex-wrap gap-1">
+      {quickTagKeys.map((key) => (
+        <Badge
+          key={key}
+          variant="outline"
+          className="border-gray-200 bg-gray-100 text-gray-700 rounded-full whitespace-nowrap font-medium"
+        >
+          {t(`aiToolQuickTag.${key}`)}
+        </Badge>
+      ))}
+    </div>
+  );
+}
