@@ -0,0 +1,43 @@
+import { NextRequest, NextResponse } from 'next/server';
+
+import { getRewrittenSearchQuery } from '@/lib/ai-tool-search';
+
+/**
+ * Rewrite natural-language search input into keywords (userNeed) for list filtering.
+ * Used only by AI tools page in "natural language" mode; keyword mode does not call this.
+ * POST body: { query: string, locale?: string }
+ * Response: { success, data: { searchQuery: string } }
+ */
+export async function POST(request: NextRequest) {
+  try {
+    const body = await request.json();
+    const query =
+      typeof body?.query === 'string' ? body.query.trim() : '';
+    const locale =
+      typeof body?.locale === 'string' ? body.locale : undefined;
+
+    if (!query) {
+      return NextResponse.json(
+        { success: false, error: 'query is required' },
+        { status: 400 }
+      );
+    }
+
+    const searchQuery = await getRewrittenSearchQuery(query, locale);
+
+    return NextResponse.json({
+      success: true,
+      data: { searchQuery }
+    });
+  } catch (error) {
+    const message =
+      error instanceof Error ? error.message : 'Rewrite failed';
+    if (process.env.NODE_ENV === 'development') {
+      console.error('[api/ai-tools/rewrite-search] POST error:', error);
+    }
+    return NextResponse.json(
+      { success: false, error: message },
+      { status: 500 }
+    );
+  }
+}
