+import { NextRequest, NextResponse } from 'next/server';
+
+import { getAiToolsForPrompt } from '@/data/ai-tool';
+import { scoreAndSortToolsByQuery } from '@/lib/ai-tool-search';
+
+const SUGGEST_LIMIT = 8;
+
+/**
+ * 即時建議 AI 工具（與 Chat searchAiTool 相同邏輯：依關鍵字在 name/description/tags 計分）
+ * GET /api/ai-tools/suggest?q=pt&locale=zh-TW
+ */
+export async function GET(request: NextRequest) {
+  try {
+    const searchParams = request.nextUrl.searchParams;
+    const q = searchParams.get('q')?.trim() ?? '';
+    const locale = searchParams.get('locale') ?? undefined;
+
+    if (!q) {
+      return NextResponse.json({ success: true, data: [] });
+    }
+
+    const list = await getAiToolsForPrompt([], locale);
+    const scored =
+      list.length > 0
+        ? scoreAndSortToolsByQuery(list, q)
+        : [];
+    const slice = scored.slice(0, SUGGEST_LIMIT);
+
+    const data = slice.map((t) => ({
+      id: t.id,
+      name: t.name ?? '',
+      slug: t.slug ?? t.id,
+      description:
+        typeof t.description === 'string'
+          ? t.description.slice(0, 120)
+          : null,
+      outputType: t.outputType ?? undefined
+    }));
+
+    return NextResponse.json({ success: true, data });
+  } catch (error) {
+    const message =
+      error instanceof Error ? error.message : '取得建議失敗';
+    if (process.env.NODE_ENV === 'development') {
+      console.error('[api/ai-tools/suggest] GET error:', error);
+    }
+    return NextResponse.json(
+      { success: false, error: message },
+      { status: 500 }
+    );
+  }
+}
